document.addEventListener("DOMContentLoaded",function(){function n(n){return n>=1e6?`$${(n/1e6).toFixed(1)}M`:n>=1e3?`$${(n/1e3).toFixed(0)}K`:n.toLocaleString("en-US",{style:"currency",currency:"USD",minimumFractionDigits:0,maximumFractionDigits:0})}function e(n){return`${n.toFixed(1)}%`}function s(n,e,s,i="info"){return`\n      <div class="insight-card ${i}">\n        <h6>${n}</h6>\n        <div class="metric-value">${e}</div>\n        <div class="metric-subtitle">${s}</div>\n      </div>\n    `}const i=document.getElementById("bike-shop-form"),t=document.getElementById("bike-shop-result");i&&i.addEventListener("submit",function(i){i.preventDefault();const a=parseInt(document.getElementById("shop-area").value),o=parseFloat(document.getElementById("initial-inventory").value),r=parseFloat(document.getElementById("renovation-equipment").value),l=parseFloat(document.getElementById("additional-costs").value),d=parseFloat(document.getElementById("avg-bike-price").value),c=parseFloat(document.getElementById("high-season-bikes").value),v=parseFloat(document.getElementById("low-season-bikes").value),p=parseFloat(document.getElementById("high-season-months").value),u=parseFloat(document.getElementById("rent").value),g=parseFloat(document.getElementById("staff-costs").value),m=parseFloat(document.getElementById("utilities").value),b=parseFloat(document.getElementById("marketing-other").value),w=parseFloat(document.getElementById("repair-revenue").value),$=parseFloat(document.getElementById("accessories-revenue").value);if(d<=0||c<=0||v<=0)return t.innerHTML='<div class="error">Please enter valid values for all fields.</div>',void 0;const h=o+r+l,f=12-p,y=c*d,k=v*d,I=y+w+$,B=k+.7*w+.8*$,F=I*p+B*f,E=12*(u+g+m+b),S=(.6*y+.5*$)*p+(.6*k+.8*$*.5)*f,x=F-S,P=x-E,A=P/12,D=P/F*100,L=x/F*100,O=h/P,R=P/h*100,C=F/a,M=(c*p+v*f)/12,z=S/o;let T="info";P<0?T="warning":D>20&&(T="success");let U="info";R<20?U="warning":R>35&&(U="success");let q="info";z<2?q="warning":z>4&&(q="success"),t.innerHTML=`\n        <div class="business-plan-results">\n          <h3>🚴 Bike Shop Business Plan Analysis</h3>\n          \n          <div class="insight-cards">\n            ${s("💰 Total Investment",n(h),"Initial capital required","info")}\n            ${s("📈 Monthly Profit",n(A),`Margin: ${e(D)}`,T)}\n            ${s("⏱️ Payback Period",`${O.toFixed(1)} years`,`ROI: ${e(R)}`,O<=3?"success":"warning")}\n            ${s("🔄 Inventory Turnover",`${z.toFixed(1)} times/year`,"Stock efficiency",q)}\n          </div>\n\n          <div class="financial-breakdown">\n            <h4>💼 Detailed Financial Analysis</h4>\n            \n            <div class="section">\n              <h5>🏗️ Startup Costs</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Initial inventory investment</span>\n                  <span>${n(o)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Renovation & equipment</span>\n                  <span>${n(r)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Licensing, marketing & other</span>\n                  <span>${n(l)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Startup Investment</strong></span>\n                  <span><strong>${n(h)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💵 Annual Revenue</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Peak season (${p} months) - bike sales</span>\n                  <span>${n(y*p)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Low season (${f} months) - bike sales</span>\n                  <span>${n(k*f)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Repair & service revenue</span>\n                  <span>${n(w*p+.7*w*f)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Accessories & parts</span>\n                  <span>${n($*p+.8*$*f)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Annual Revenue</strong></span>\n                  <span><strong>${n(F)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💸 Annual Expenses</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Cost of goods sold (COGS)</span>\n                  <span>${n(S)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Store rent</span>\n                  <span>${n(12*u)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Staff salaries</span>\n                  <span>${n(12*g)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Utilities</span>\n                  <span>${n(12*m)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Marketing & other expenses</span>\n                  <span>${n(12*b)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Annual Expenses</strong></span>\n                  <span><strong>${n(S+E)}</strong></span>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card info">\n              <h6>🏪 Store Efficiency</h6>\n              <div class="metric-subtitle">\n                Revenue per sq ft: <strong>${n(C)}/year</strong><br>\n                Bikes per month: <strong>${M.toFixed(1)} units</strong><br>\n                Gross margin: <strong>${e(L)}</strong>\n              </div>\n            </div>\n            <div class="insight-card ${P>0?"success":"warning"}">\n              <h6>📊 Seasonal Analysis</h6>\n              <div class="metric-subtitle">\n                Peak season: <strong>${n(I)}/month</strong><br>\n                Low season: <strong>${n(B)}/month</strong><br>\n                Seasonal variance: <strong>${e((I-B)/B*100)}</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card ${A>0?"success":"warning"}">\n              <h6>📈 Profitability Forecast</h6>\n              <div class="metric-subtitle">\n                Annual profit: <strong>${n(P)}</strong><br>\n                Weekly profit: <strong>${n(P/52)}</strong><br>\n                Daily profit: <strong>${n(P/365)}</strong>\n              </div>\n            </div>\n            <div class="insight-card info">\n              <h6>💡 Optimization Potential</h6>\n              <div class="metric-subtitle">\n                Gross profit: <strong>${n(x)}</strong><br>\n                Operating expenses: <strong>${n(E)}</strong><br>\n                Cost reduction opportunity: <strong>${e(E/F*100)}</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="recommendations">\n            <h4>🎯 Optimization Recommendations</h4>\n            <ul>\n              ${D<15?"<li>⚠️ Low profitability. Consider increasing prices or reducing costs.</li>":""}\n              ${z<2?"<li>📦 Low inventory turnover. Improve product mix or reduce stock levels.</li>":""}\n              ${O>4?"<li>⏰ Long payback period. Optimize startup costs or increase sales.</li>":""}\n              ${z>5?"<li>✅ High turnover! Consider expanding inventory or store size.</li>":""}\n              ${D>25?"<li>🎉 Excellent profitability! Consider opening additional location.</li>":""}\n              <li>🔧 Develop service offerings for stable revenue stream.</li>\n              <li>🛒 Add online sales to expand customer base.</li>\n              <li>🎯 Focus on high-margin accessories and services.</li>\n              <li>🤝 Partner with cycling clubs and sports organizations.</li>\n              <li>📱 Use social media to attract customers and build community.</li>\n              <li>⭐ Implement loyalty programs for repeat customers.</li>\n              <li>🎪 Organize cycling events and new model test rides.</li>\n              <li>❄️ Develop winter inventory: skis, snowboards, winter service.</li>\n              <li>🚴 Offer bike fitting and customization services.</li>\n              <li>📊 Use data analytics to optimize inventory management.</li>\n            </ul>\n          </div>\n\n          <div class="print-section">\n            <button onclick="window.print()" class="print-btn">🖨️ Print Business Plan</button>\n            <button onclick="downloadCSV()" class="download-btn">📥 Download Data (CSV)</button>\n          </div>\n        </div>\n      `,window.bikeShopBusinessData={"Store Size (sq ft)":a,"Total Investment ($)":h,"Annual Revenue ($)":F,"Annual Expenses ($)":S+E,"Annual Profit ($)":P,"Monthly Profit ($)":A,"Profit Margin (%)":D,"Annual ROI (%)":R,"Payback Period (years)":O,"Inventory Turnover":z,"Revenue per sq ft ($)":C,"Average Bike Price ($)":d}}),window.downloadCSV=function(){if(!window.bikeShopBusinessData)return;const n=Object.entries(window.bikeShopBusinessData).map(([n,e])=>`"${n}","${"number"==typeof e?e.toFixed(2):e}"`).join("\n"),e=new Blob(["\ufeffMetric,Value\n"+n],{type:"text/csv;charset=utf-8;"}),s=document.createElement("a");s.href=URL.createObjectURL(e),s.download="bike-shop-business-plan.csv",s.click()}});